void pwm_duty_init(void)
{
    gpio_init(Dir_Left, GPO, GPIO_HIGH, GPO_PUSH_PULL);                           // GPIO 初始化为输出 默认上拉输出高
    pwm_init(Motor_Left, 25000, 0);                                                 // PWM 通道初始化频率 17KHz 占空比初始为 0
    gpio_init(Dir_Right, GPO, GPIO_HIGH, GPO_PUSH_PULL);                           // GPIO 初始化为输出 默认上拉输出高
    pwm_init(Motor_Right, 25000, 0);                                                 // PWM 通道初始化频率 17KHz 占空比初始为 0
}


void encoder_init(void)
{
    encoder_dir_init(ENCODER_left, ENCODER_left_ch1, ENCODER_left_ch2);                      // 初始化编码器模块与引脚 方向解码编码器模式
    encoder_dir_init(ENCODER_right, ENCODER_right_ch1, ENCODER_right_ch2);                      // 初始化编码器模块与引脚 方向解码编码器模式
}



void Motor_Out(int16 pwm_left_set,int16 pwm_right_set)
{
/*******************************************************************************/
//给电机加入死区，否则速度设为0时电机方向来回跳变很容易发烫
    if((abs(pwm_left_set)) < 15)
    {
        pwm_left_set = 0;
    }
    if((abs(pwm_right_set)) < 15)
    {
        pwm_right_set = 0;
    }
/*******************************************************************************/
    if(pwm_left_set >= 0)
    {
        gpio_set_level(Dir_Left, Left_forward_dir);
        pwm_set_duty(Motor_Left, pwm_left_set);
    }
    else
    {
        gpio_set_level(Dir_Left, Left_reverse_dir);
        pwm_set_duty(Motor_Left, - pwm_left_set);
    }

    if(pwm_right_set >= 0)
    {
        gpio_set_level(Dir_Right, right_forward_dir);
        pwm_set_duty(Motor_Right, pwm_right_set);
    }
    else
    {
        gpio_set_level(Dir_Right, right_reverse_dir);
        pwm_set_duty(Motor_Right, - pwm_right_set);
    }
}


void encoder_count_get(void)
{
    encoder_L = encoder_get_count(ENCODER_left);                              // 获取编码器计数
    encoder_R = -encoder_get_count(ENCODER_right);                              // 获取编码器计数

    //缓加，防止设定速度跳变烧电机
    if(encoder_L > Last_encoder_L + 20.0)       encoder_L = Last_encoder_L + 20.0;
    else if(encoder_L < Last_encoder_L - 20.0)  encoder_L = Last_encoder_L - 20.0;
    if(encoder_R > Last_encoder_R + 20.0)       encoder_R = Last_encoder_R + 20.0;
    else if(encoder_R < Last_encoder_R - 20.0)  encoder_R = Last_encoder_R - 20.0;

    Last_encoder_L = encoder_L;
    Last_encoder_R = encoder_R;

    encoder_clear_count(ENCODER_left);                              // 清空编码器计数
    encoder_clear_count(ENCODER_right);                             // 清空编码器计数

    //这部分是编码器的累加数值
    encoder_ave = (encoder_L + encoder_R) / 2;
    encoder_L_total += encoder_L;
    encoder_R_total += encoder_R;
    encoder_total += encoder_ave;

}


void Brushless_Motor_Speed(uint16 Brushless_Speed)
{
    //无刷负压电机
    //一般来说直接设定pwm_set_duty(Brushless_Motor, Brushless_Motor_out);就好。我这里采用缓慢启动，更容易启动成功
    //(在50HZ的频率下给到500-1000的占空比)(500开始转动,1000达到满转)

    Brushless_count ++;
    if(Brushless_count > 5000)Brushless_count = 5000;
    if(Brushless_Speed > Brushless_PWM_Max_percentage)
        Brushless_Speed = Brushless_PWM_Max_percentage;
    if(Brushless_Motor_out > Brushless_PWM_Max_percentage)
    {
        Brushless_Motor_out = 0;
    }

    if(Brushless_Motor_begin_flag == 1)
    {
        if(Brushless_Motor_out < Brushless_Speed)
            Brushless_Motor_out += FAN_RAMP_STEP;
        if(Brushless_Motor_out > Brushless_Speed)
            Brushless_Motor_out = Brushless_Speed;
    }
    else
    {
        Brushless_Motor_out = 0;
    }
    pwm_set_duty(Brushless_Motor, Brushless_Motor_out);
}


void speed_control(void)
{
//这部分是缓加速和缓减速
//在发车时缓慢加速可以有效防止翘头的情况
//速度决策时缓加速和缓减速可以让车辆行进更流畅

    if(Loop_Set == Loop_Type_Deviation)
    {
        /* ==================== 参数区 ==================== */
        #define ACCEL_STEP     20      /* 加速系数，每5ms加 x */
        #define DECEL_STEP     20      /* 减速系数，每5ms减 x */
        #define LAUNCH_KICK    30       /* 起步助力，0=禁用 */
        /* ============================================== */


        int16 target = speed_target();      //直角元素进行中限速，转弯、偏线时按速度规划减速
        if (launch_flag == 1 && launch_delay_flag == 0 && IMUinit_flag == 0)
        {
            if (LAUNCH_KICK > 0 && set_speed == 0)
            {
                set_speed = LAUNCH_KICK;
                if(launch_time == 0)launch_time = 1;
                if (set_speed > target)
                    set_speed = target;
            }
            /* 加速：加了会超就直接到目标 */
            else if (set_speed < target)
            {
                if(launch_time == 1)
                {
                    if (set_speed + 10 > target)
                    {
                        set_speed = target;
                        launch_time = 2;
                    }
                    else
                        set_speed += 10;
                }
                else
                {
                    if (set_speed + ACCEL_STEP > target)
                        set_speed = target;
                    else
                        set_speed += ACCEL_STEP;
                }
            }
            /* 减速：目标被调小，减了会低过目标就直接到目标 */
            else if (set_speed > target)
            {
                if (set_speed - DECEL_STEP < target)
                    set_speed = target;
                else
                    set_speed -= DECEL_STEP;
            }
        }
        else if (launch_flag == 0)
        {
            launch_time = 0;
            /* 停车：向 0 靠拢，同样防越界 */
            if (set_speed > 0)
            {
                if (set_speed - DECEL_STEP < 0)
                    set_speed = 0;
                else
                    set_speed -= DECEL_STEP;
            }
            else if (set_speed < 0)
            {
                if (set_speed + DECEL_STEP > 0)
                    set_speed = 0;
                else
                    set_speed += DECEL_STEP;
            }
        }

    }
    else
    {
        if(launch_flag == 1 && launch_delay_flag == 0 && IMUinit_flag == 0)
        {
            set_speed = set_speed_surface;
        }
        else if(launch_flag == 0)
        {
            set_speed = 0;
        }

    }
}

