//-------------------------------------------------------------------------------------------------------------------
//函数名称：void flash_memery_write(uint8(*image)[image_w])
//功能说明：存路径数据
//参数说明：
//函数返回：无
//备    注：
//example： flash_memery_write(&flash_pid_write, pid_adjust_INDEX);
//-------------------------------------------------------------------------------------------------------------------
void flash_memery_write(void (*flash_write_pointer)(void), uint8 flash_index)
{
    // 第一步清除缓冲区
    flash_buffer_clear();
    // 第二步把数据存到缓冲区
    flash_write_pointer();
    // 第三步判断FLASH里有没有数据，有就把FLASH数据擦除/把数据存到缓冲区
    if (flash_check(FLASH_SECTION_INDEX, flash_index))
    { // 判断是否有数据
        flash_erase_page(FLASH_SECTION_INDEX, flash_index);
    } // 擦除这一页
    // 第四步存到FLASH指定扇区
    flash_write_page_from_buffer(FLASH_SECTION_INDEX, flash_index);
    // 存取过程结束 —— 成功存取
}



//-------------------------------------------------------------------------------------------------------------------
//函数名称：void flash_memery_read(void (*flash_read_pointer)(void), uint8 flash_index)
//功能说明：取路径数据
//参数说明：&flash_pid_read   储存数据的函数
//         flash_index       要存储的扇区
//函数返回：
//备    注：
//example： flash_memery_read(&flash_pid_read, pid_adjust_INDEX);
//-------------------------------------------------------------------------------------------------------------------
void flash_memery_read(void (*flash_read_pointer)(void), uint8 flash_index)
{
    if (flash_check(FLASH_SECTION_INDEX, flash_index)) // 检查flash里面是否存了数据
    {
        flash_read_page_to_buffer(FLASH_SECTION_INDEX, flash_index);
        flash_read_pointer();
    }
}



//检测要存到flash里的数据是否变化
void flash_change_check(void)
{

    if(pid_flash_flag == write_begin)
    {
        flash_memery_write(&flash_pid_write, pid_adjust_INDEX);
        pid_flash_flag = write_over;
    }
    if(pid_flash_flag == read_begin)//想存的时候就让 pid_flash_flag == write_begin
    {
        flash_memery_read(&flash_pid_read, pid_adjust_INDEX);
        pid_flash_flag = read_over;
    }


}



