void imu_calibration_reset(uint8 start)
{
    boolean enabled = IfxCpu_disableInterrupts();
    gyroz_zero_nouse = 0;
    Tune_Aid_imu = 0;
    IMUinit_flag = start;
    IfxCpu_restoreInterrupts(enabled);
}

//-------------------------------------------------------------------------------------------------------------------
//函数名称：void Gyro_Translate(void)
//功能说明：陀螺仪数据解算
//参数说明：无
//函数返回：无
//备    注：
//example： Gyro_Translate();
//-------------------------------------------------------------------------------------------------------------------
void Gyro_Translate(void)
{
    float gyroz;
    float gyroz2;
    static float last_gyroz;
    imu660rc_get_acc();
    imu660rc_get_gyro();

//Gyro_Data_z陀螺仪的加速度数值
//imu_sum陀螺仪转动的角度(实测非常好用)。通过改Gyro_Coefficient来达到现实中的比例(转一圈360°)
/*******************************************************************************/
//这个地方是为了在发车前去除陀螺仪的零漂
    if(IMUinit_flag == 1)
    {
        Gyro_zero_buffer = departure_zero_buffer / Tim_imu;

        gyroz_zero_nouse += imu660rc_gyro_z;
        Tune_Aid_imu ++;
        if(Tune_Aid_imu == Gyro_zero_buffer)
        {
            Tune_Aid_imu = 0;
            gyroz_zero = gyroz_zero_nouse / Gyro_zero_buffer;
            IMUinit_flag = 0;
            imu_sum = 0;
        }

    }
/*******************************************************************************/
    if(IMUinit_flag == 0)
    {
        //陀螺仪偏航角数据解算
        Gyro_Unfinished_z = (imu660rc_gyro_z - gyroz_zero);
        gyroz = imu660rc_gyro_transition(Gyro_Unfinished_z);
        Gyro_Data_z = sliding_window_filter(gyroz_filter, gyroz, 10);
        if(Gyro_Data_z < 1.6 && Gyro_Data_z > - 1.6)    Gyro_Data_z = 0;//这句是因为开了负压会抖动，加个死区来防止抖动，你可以开着负压，看Gyro_Data_z在静止状态下最多跳变到多少，这个值就填多少


        //陀螺仪姿态解算
        gyroz = 0.4 * gyroz + 0.6 * last_gyroz;
        gyroz2 = (int16)gyroz * Gyro_Coefficient;
        imu_sum += gyroz2;


        err_angle = target_imu - imu_sum;//大于0向左转
        last_gyroz = gyroz;
        //左加右减


    }

}


//-------------------------------------------------------------------------------------------------------------------
//函数名称：void imu_zero_init(void)
//功能说明：陀螺仪数据解算
//参数说明：无
//函数返回：无
//备    注：
//example： imu_zero_init();
//-------------------------------------------------------------------------------------------------------------------
void imu_zero_init(void)
{
    //这部分是初始化时去除零漂，后面会在发车前再去除一次，所以这部分是为了看陀螺仪处理后的数值
    gyroz_zero = 0;
    Gyro_zero_buffer = departure_zero_buffer / Tim_imu;

    for (uint16_t i = 0; i < Gyro_zero_buffer; i++)
    {
        imu660rc_get_gyro();
        gyroz_zero += imu660rc_gyro_z;
        system_delay_ms(Tim_imu);
    }

    gyroz_zero /= Gyro_zero_buffer;
    gyroz_zero_nouse = 0;
}



//-------------------------------------------------------------------------------------------------------------------
//函数名称：sliding_window_filter(float* input, float newdata ,int length)
//功能说明：滑动平均滤波
//参数说明：无
//函数返回：无
//备    注：
//example： sliding_window_filter(gryoz, Gyro_Data.z, 10);
//-------------------------------------------------------------------------------------------------------------------
float sliding_window_filter(float* input, float newdata ,int length)
{
    int i = 0,count = 0;
    float sum = 0;
    for(i = 0; i < length - 1; i ++)
        {
            input[i] = input[i + 1];
            if(input[i] != 0)
            {
                sum += input[i];
                count ++;
            }
        }
        input[length - 1] = newdata;
        sum += input[length - 1];
        return sum / (count + 1);
}

