uint8 non_blocking_delay(uint32 delay_ms)
{
    if (!delay_active)
    {
        delay_started_ms = timing_count;
        delay_active = 1;
    }
    if ((uint32)(timing_count - delay_started_ms) < delay_ms) return 0;
    delay_active = 0;
    return 1;
}

// 计算 a 的 x 次方（x 为整数）
// 返回值：成功返回结果，失败（如 0^0、负数开偶次幂）返回 0 并提示
float power_int(float a, int x)
{
    float result = 1.0;
    int abs_x = x; // 先取 x 的绝对值，统一处理乘法逻辑

    // 特殊情况判断（避免无意义计算或错误）
    if (a == 0.0)
    {
        if (x == 0)
        {
            return 0.0;
        }
        return 0.0; // 0 的正次幂是 0，负次幂无意义（返回 0 或报错均可）
    }
    if (x < 0)
    {
        abs_x = -x; // 负指数 → 先算正指数，最后取倒数
    }

    // 循环累乘：result = a * a * ... * a（abs_x 次）
    for (int i = 0; i < abs_x; i++)
    {
        result *= a;
    }

    // 处理负指数：结果取倒数
    return x < 0 ? 1.0 / result : result;
}




