/* pixel-equivalent of 5cm at each row (vertical gap limit base) */
static const uint8 Length_5cm[MT9V03X_H] = {
    10,10,10,10,10,10,10,10,10,10,    /* row   0- 9 (far)    */
    10,10,10,10,10,10,10,10,10,10,    /* row  10-19          */
