/* OUC line.c: ordinary/one-side lookahead branch; no route decisions. */
#include "maze.h"
#include "line.h"
static Point R,L,M;
static int error;
int normal_front_point = 85;
int L_R_difference;
int get_angle(int x,int y){
    x = (MT9V03X_W/2)-x;
    y = MT9V03X_H - y;
    int result = (int)(atan2f(x, y) * 180.0f / M_PI);
    return result;
}

Point average_point(Point *Pointin,int min,int max){
    Point sum;
    sum.x = 0;
    sum.y = 0;
    int count = 0;

    for(int i=min;i<max;i++){
        sum.x += Pointin[i].x;
        sum.y += Pointin[i].y;
        count +=  1;
    }

    sum.x = sum.x/count;
    sum.y = sum.y/count;
    return sum;
}

void caculate_error(void)
{
    int front_point = normal_front_point;
    int average_range = 5;
    uint8_t R_fail = 0, L_fail = 0;
    if (L_point>front_point){
        L = average_point(Side_L,front_point-average_range,front_point);

    }else if(L_point>40){
        L = average_point(Side_L,L_point-average_range,L_point);
    }else if(L_point>20){
        L = average_point(Side_L,15,20);
    }else{
        if(L_point>0){
            L = Side_L[L_point-1];
        }else{
            L_fail = 1;
        }
    }
    if (R_point>front_point){
        R = average_point(Side_R,front_point-average_range,front_point);
    }else if(R_point>40){
        R = average_point(Side_R,R_point-average_range,R_point);
    }else if(R_point>20){
        R = average_point(Side_R,15,20);
    }else{
        if(R_point>0){
            R = Side_R[R_point-1];
        }else{
            R_fail = 1;
        }
    }

    if(L_fail && !R_fail) L = R;
    if(R_fail && !L_fail) R = L;

    M.x = (L.x+R.x)/2;
    M.y = (L.y+R.y)/2;
    int M_result = get_angle(M.x,M.y);
    int L_result = get_angle(L.x,L.y);
    int R_result = get_angle(R.x,R.y);


    L_R_difference = L_result - R_result;
    if (R_fail) {
        error = L_result;
        L_R_difference = 0;
    } else if (L_fail) {
        error = R_result;
        L_R_difference = 0;
    } else {
        error = M_result;
    }
}
int return_error(void) { return error; }

