/* Captain's image_error: his Weighting_20 table over the 20 rows around the middle row (rows 50..69). */
#define GAUSS_ROWS      20
#define GAUSS_ROW_FIRST (MT9V03X_H / 2 - GAUSS_ROWS / 2)
static const float gauss_w[GAUSS_ROWS] = {
    0.020f, 0.032f, 0.050f, 0.076f, 0.112f,
    0.158f, 0.215f, 0.284f, 0.364f, 0.450f,
    0.450f, 0.364f, 0.284f, 0.215f, 0.158f,
    0.112f, 0.076f, 0.050f, 0.032f, 0.020f
};
static uint8 track_width[MT9V03X_H];   /* per-row width learned when both edges are seen; 0 = unknown */

void ouc_vision_init(void)
{
    ouc_image_reset();
    L_point = R_point = 0;
    memset(Side_L, 0, sizeof Side_L);
    memset(Side_R, 0, sizeof Side_R);
    memset(&exit_record, 0, sizeof exit_record);
    memset(track_width, 0, sizeof track_width);
}

/* First crawler point that reaches a window row is that side's boundary on the row; -1 = not reached. */
static void window_edges(const Point *side, int n, int16_t *edge)
{
    for (int k = 0; k < GAUSS_ROWS; k++) edge[k] = -1;
    for (int i = 0; i < n; i++)
    {
        int k = side[i].y - GAUSS_ROW_FIRST;
        if (k >= 0 && k < GAUSS_ROWS && edge[k] < 0) edge[k] = (int16_t)side[i].x;
    }
}

uint8_t ouc_gaussian_deviation(int16_t *px)
{
    int16_t l[GAUSS_ROWS], r[GAUSS_ROWS];
    float sum_w = 0.0f, sum_wd = 0.0f, all_w = 0.0f, c, dev;
    window_edges(Side_L, L_point, l);
    window_edges(Side_R, R_point, r);
    for (int k = 0; k < GAUSS_ROWS; k++)
    {
        int y = GAUSS_ROW_FIRST + k;
        all_w += gauss_w[k];
        if (l[k] >= 0 && r[k] > l[k])
        {
            uint8 w = (uint8)(r[k] - l[k]);
            track_width[y] = track_width[y] ? (uint8)((3 * track_width[y] + w) / 4) : w;
            c = 0.5f * (float)(l[k] + r[k]);
        }
        /* one edge only: shift it by half the width learned on this row */
        else if (l[k] >= 0 && track_width[y]) c = (float)l[k] + 0.5f * track_width[y];
        else if (r[k] >= 0 && track_width[y]) c = (float)r[k] - 0.5f * track_width[y];
        else continue;
        sum_w += gauss_w[k];
        sum_wd += gauss_w[k] * (c - (float)(MT9V03X_W / 2));
    }
    /* shortcut: under a quarter of the window weight counts as lost; tune on real images. */
    if (sum_w < 0.25f * all_w) return 0;
    dev = sum_wd / sum_w;
    *px = (int16_t)(dev >= 0.0f ? dev + 0.5f : dev - 0.5f);
    return 1;
}

/* Right angle, structure of SoberUp check_sharp_turn_state (element_line.c); thresholds are ours, set on the simulator's
 * rendered camera (F:/TC264/sim-tune cam=1, SoberUp camera calibration) and still to be checked on real frames.
 * Both crawlers leave through the same side and neither reaches the top. A 60-degree corner or a tight arc leaves the same
 * way, so the inner crawler (the one on the turn side) must also run nearly level along the new branch: from where it has
 * moved RA_CORNER_DX columns sideways to where it leaves the image it may climb at most 1 row per RA_LEVEL_RUN columns,
 * and it must leave below row RA_MIN_ROW (far 60-degree corners and arcs leave higher). */
#define RA_CORNER_DX  20
#define RA_LEVEL_RUN  5
#define RA_MIN_ROW    36

int8_t ouc_right_angle(uint8_t *row)
{
    const ExitPoint *ex;
    const Point *in;
    int8_t dir;
    int i, n;
    if (row == NULL || L_point <= 0 || R_point <= 0) return 0;   /* exit_record is stale when no crawl ran */
    if (exit_record.top.L_hit || exit_record.top.R_hit) return 0;
    if (exit_record.left[0].L_hit && exit_record.left[0].R_hit) { dir = 1; in = Side_L; ex = &exit_record.left[0].L; }
    else if (exit_record.right[0].L_hit && exit_record.right[0].R_hit) { dir = -1; in = Side_R; ex = &exit_record.right[0].R; }
    else return 0;
    n = ex->step_idx;
    if (ex->pt.y < RA_MIN_ROW || n <= 0 || n > (dir > 0 ? L_point : R_point)) return 0;
    for (i = 0; i < n && abs(in[i].x - in[0].x) < RA_CORNER_DX; i++) {}
    if (i >= n || (in[i].y - ex->pt.y) * RA_LEVEL_RUN > abs(ex->pt.x - in[i].x)) return 0;
    *row = (uint8_t)in[i].y;
    return dir;
}

int16_t ouc_vision_process(const uint8_t *frame, uint8_t *valid)
{
    int16_t result;
    if (valid == NULL) return 0;
    *valid = 0U;
    if (frame == NULL) return 0;
    memcpy(ouc_frame, frame, sizeof ouc_frame);
    binarization(otsuThreshold_fast());
    /* shortcut: no map yet; route owner must explicitly select gap fill mode. */
    Dashedline_Makeup(FILL_NONE);
    search_line_main();
    /* Preserve OUC's both-sides-lost threshold, but report immediately. */
    if (L_point < 10 && R_point < 10) return 0;
    if (!ouc_gaussian_deviation(&result)) return 0;
    *valid = 1U;
    return result;
}

