void PID_Init(void)
{
    //左右电机积分最大值
    motorL_pid.Ki.MaxValue = 5500;
    motorL_pid.Ki.MinValue = -5500;
    motorR_pid.Ki.MaxValue = 5500;
    motorR_pid.Ki.MinValue = -5500;

    //左右电机pwm最大值
    motorL_pid.MaxValue = 8500;
    motorL_pid.MinValue = -8500;
    motorR_pid.MaxValue = 8500;
    motorR_pid.MinValue = -8500;

    //角速度环积分最大值
    Angle_pid.Ki.MaxValue = 4000;
    Angle_pid.Ki.MinValue = -4000;

    //角速度环输出最大值
    Angle_pid.MaxValue = 5000;
    Angle_pid.MinValue = -5000;

    //角度环输出最大值(定义为0不限幅)
    Deviation_pid.MaxValue = 0;
    Deviation_pid.MinValue = 0;

    //电机速度环pid
    motorL_pid.Kp.present = 25;
    motorL_pid.Ki.present = 1.6;

    motorR_pid.Kp.present = 24.8;
    motorR_pid.Ki.present = 1.62;

    //陀螺仪角速度环pid: 仿真预设(F:/TC264/sim-tune 2026-10-20), 队长原值 0.083 / 0.008
    Angle_pid.Kp.present = 0.4;
    Angle_pid.Ki.present = 0.025;

    //角度环pid

    //仿真预设: 150/200/250/300/350 档调出的 Kp/Kd, 中间按速度线性插值, 两头取端点
    //队长原表: 默认 28.2/46; 250:17.8/48 300:22.8/60 350:26.8/95 390:28.4/114 410:30.6/128 430:32.3/158
    {
        static const float at[5] = {150, 200, 250, 300, 350};
        static const float kp[5] = {8, 12, 12, 12, 12};
        static const float kd[5] = {0, 15, 46, 70, 70};
        for (int i = 0; i < Speed_max; i ++)
        {
            float s = (float)(i * 10);
            int k = 0;
            while (k < 3 && s > at[k + 1]) k ++;
            float f = func_limit_ab((s - at[k]) / (at[k + 1] - at[k]), 0.0f, 1.0f);
            Deviation_pid.Kp.speed[i] = kp[k] + f * (kp[k + 1] - kp[k]);
            Deviation_pid.Kd.speed[i] = kd[k] + f * (kd[k + 1] - kd[k]);
        }
    }

    Deviation_pid.Kp.speed[Speed_zip(0)] = 0;
    Deviation_pid.Kd.speed[Speed_zip(0)] = 0;



}

void PID_Control_Inc(PID* pid, int16 SetValue, int16 ActValue)//增量式pid
{
    float A = 0.9;//低通滤波系数
    pid->last_PIDout = pid->PIDout;
    pid->SetValue = SetValue;
    pid->ActValue = ActValue;
    pid->error = pid->SetValue - pid->ActValue;

    pid->integral = pid->Kp.present * (pid->error - pid->last_error) + pid->Ki.present * pid->error;
    pid->last_error = pid->error;

    if(pid->Ki.MaxValue != 0 || pid->Ki.MinValue != 0)//都为0的时候不限幅
    {
        pid->integral = (pid->integral > pid->Ki.MaxValue) ? pid->Ki.MaxValue :
                        (pid->integral < pid->Ki.MinValue) ? pid->Ki.MinValue :
                                                             pid->integral;
    }
    pid->PIDout += pid->integral;
    if(pid->MaxValue != 0 || pid->MinValue != 0)//都为0的时候不限幅
    {
        pid->PIDout = (pid->PIDout > pid->MaxValue) ? pid->MaxValue :
                      (pid->PIDout < pid->MinValue) ? pid->MinValue :
                                                      pid->PIDout;
    }
    pid->PIDout = pid->PIDout * A + pid->last_PIDout * (1 - A);  // 应用低通滤波
}


void PID_Control_Pos(PID* pid, int16 SetValue, int16 ActValue)//位置式pid
{
    float A = 0.9;//低通滤波系数
    pid->last_PIDout = pid->PIDout;
    pid->SetValue = SetValue;
    pid->ActValue = ActValue;
    pid->error = pid->SetValue - pid->ActValue;
    pid->PIDout = pid->Kp.speed[Speed_index(speed_target())] * pid->error + pid->Kd.speed[Speed_index(speed_target())] * (pid->error - pid->last_error);
    pid->last_error = pid->error;

    if(pid->MaxValue != 0 || pid->MinValue != 0)//都为0的时候不限幅
    {
        pid->PIDout = (pid->PIDout > pid->MaxValue) ? pid->MaxValue :
                      (pid->PIDout < pid->MinValue) ? pid->MinValue :
                                                      pid->PIDout;
    }
    pid->PIDout = pid->PIDout * A + pid->last_PIDout * (1 - A);  // 应用低通滤波
}


static void pid_reset_history(PID *pid)
{
    pid->integral = pid->error = pid->last_error = 0;
    pid->PIDout = pid->last_PIDout = 0;
}

/* 直角（90° 弯，2026-10-20，仿真验证，实车待测）。视觉认出（ouc_right_angle）后：
 *   1 限速 ra_speed，继续寻线；
 *   2 拐角快进中间行加权窗口（到第 RA_HOLD_ROW 行）或中间行丢线：陀螺保持当时的航向（横线会把偏差带偏、提前切弯）；
 *   3 拐角走到第 ra_turn_row 行（或在近处看不到了）：目标航向 ±90°，外环改跟 angle_error；
 *   离目标 ra_exit_deg 度以内、又看到线，回到寻线。
 * 认错了：状态 1 连续 RA_FALSE_FRAMES 帧看不到拐角就撤销；状态 2 拐角还在远处就看不到了，也撤销。
 * 状态 2、3 超过 1 s 还没回到线上就停车，STOP_reason = 4。
 * angle_error：度，左正，= target_imu − imu_sum（同 imu.c 的 err_angle）。
 * 元素进行中，方向环增益按限速后的速度档取（speed_target，含速度规划）：高速档的增益在低速会来回振荡。 */
#define RA_CONFIRM_FRAMES  3      //连续几帧看到才算
#define RA_FALSE_FRAMES    20     //状态 1：连续这么多帧看不到拐角、线还在 → 撤销
#define RA_GONE_FRAMES     2      //状态 2：拐角连续这么多帧看不到 → 已到车前（或认错了）
#define RA_HOLD_ROW        45     //拐角到这一行（中间行窗口 50～69 之上一点）就改陀螺保持航向
#define RA_NEAR_ROWS       15     //状态 2：最后看到时离 ra_turn_row 不到这么多行，算“到车前了”
#define RA_TIMEOUT_TICKS   200    //状态 2、3 超过 1 s → 停车
#define RA_ARM_RATE        150    //车正在转弯（陀螺超过 150 度/秒）时不认：60° 弯转到一半，画面也像直角 [仿真]
int16 ra_speed = 80;              //直角限速（编码器计数 / 2 ms）[仿真]
uint8 ra_turn_row = 95;           //拐角到这一行开始转（仿真相机约车前 13 cm）[仿真]，装好相机后实测
uint8 ra_exit_deg = 20;           //离目标航向几度以内、又看到线就回寻线 [仿真]
int16 ra_rate = 360;              //转弯时角速度目标上限（度/秒）：转弯半径 ≈ 车速 ÷ 角速度，不随电机快慢变 [仿真]
uint8 ra_state = 0;               //0 寻线，1 看到直角，2 保持航向，3 转 90°
static int8 ra_dir;               //+1 左，-1 右
static uint8 ra_seen, ra_miss, ra_row, ra_kick;
static uint16 ra_ticks;
static uint32 ra_seq;

static void ra_go(uint8 state)
{
    ra_state = state;
    ra_ticks = 0;
    ra_kick = 1;                  //参考值变了：下一次外环不算这一跳的微分
}

int16 ra_speed_target(void)       //发车目标速度；直角元素进行中限到 ra_speed
{
    return (ra_state != 0 && ra_speed < set_speed_surface) ? ra_speed : set_speed_surface;
}

/* 速度规划（2026-10-20，仿真定参，实车待测）：车在转弯、或线偏得多，就把目标速度往 plan_min 压，不需要地图。
 *   r = plan_wg * (陀螺 / plan_rate)^2 + (1 - plan_wg) * (偏差 / plan_px)^2，封顶 1；目标 = 上限 - r * (上限 - plan_min)。
 * 结构学去年校赛第一 Sky-Masterminds-2（PID_Controller.c:590–624，陀螺 0.7 + 偏差 0.3 两个平方），数字是我们仿真定的。
 * 只往下压：上限仍是手机设的速度（直角元素进行中是 ra_speed）。plan_min = 0 关闭，和改前完全一样。 */
int16 plan_min = 0;               //弯里最低速度（编码器计数 / 2 ms），0 = 不规划
int16 plan_rate = 400;            //角速度到这么大（度/秒）单独就压到 plan_min
int16 plan_px = 40;               //偏差到这么大（像素）单独就压到 plan_min
float plan_wg = 0.7f;             //陀螺通道权重，偏差通道 1 - plan_wg

int16 speed_target(void)          //发车目标速度：ra_speed_target 再按转弯和偏差往下压
{
    int16 top = ra_speed_target();
    float g, e, r;
    if (plan_min <= 0 || plan_min >= top) return top;
    g = Gyro_Data_z / (float)plan_rate;
    e = image_error / (float)plan_px;
    r = plan_wg * g * g + (1.0f - plan_wg) * e * e;
    if (r > 1.0f) r = 1.0f;
    return (int16)(top - r * (float)(top - plan_min));
}

static void ra_heading(float target, uint8 state)
{
    target_imu = target;
    imu_angle_flag = 1;
    ra_go(state);
}

static void right_angle_update(uint8 line_seen)
{
    int8_t dir;
    uint8_t row;
    uint32_t seq;
    seq = vision_link_corner(&dir, &row);
    if (Loop_Set != Loop_Type_Deviation || !launch_flag || launch_delay_flag || IMUinit_flag)
    {
        ra_state = ra_seen = ra_miss = 0;
        ra_seq = seq;             //停车时看到的不算
        imu_angle_flag = 0;
        return;
    }
    if (seq != ra_seq)            //来了新的一帧
    {
        ra_seq = seq;
        if (dir != 0 && (ra_state == 0 || dir == ra_dir))
        {
            if (dir != ra_dir) ra_seen = 0;
            ra_dir = dir;
            ra_row = row;
            ra_miss = 0;
            if (ra_seen < 255) ra_seen ++;
        }
        else
        {
            ra_seen = 0;
            if (ra_miss < 255) ra_miss ++;
        }
    }
    if (ra_ticks < 65535) ra_ticks ++;
    switch (ra_state)
    {
    case 0:
        if (ra_seen >= RA_CONFIRM_FRAMES && Gyro_Data_z < RA_ARM_RATE && Gyro_Data_z > -RA_ARM_RATE) ra_go(1);
        break;
    case 1:
        if (ra_miss == 0 && ra_row >= ra_turn_row)
            ra_heading(imu_sum + 90.0f * ra_dir, 3);
        else if (!line_seen || (ra_miss == 0 && ra_row >= RA_HOLD_ROW))
            ra_heading(imu_sum, 2);
        else if (ra_miss >= RA_FALSE_FRAMES)
            ra_go(0);
        break;
    case 2:
        if ((ra_miss == 0 && ra_row >= ra_turn_row) || (ra_miss >= RA_GONE_FRAMES && ra_row + RA_NEAR_ROWS >= ra_turn_row))
            ra_heading(target_imu + 90.0f * ra_dir, 3);
        else if (ra_miss >= RA_GONE_FRAMES)       //远处就看不到了：不是直角
        {
            imu_angle_flag = 0;
            ra_go(0);
        }
        else if (ra_ticks > RA_TIMEOUT_TICKS)
        {
            launch_flag = 0;
            STOP_reason = 4;
        }
        break;
    default:
        if (line_seen && target_imu - imu_sum <= ra_exit_deg && imu_sum - target_imu <= ra_exit_deg)
        {
            imu_angle_flag = 0;
            ra_seen = 0;
            ra_go(0);
        }
        else if (ra_ticks > RA_TIMEOUT_TICKS)
        {
            launch_flag = 0;
            STOP_reason = 4;
        }
        break;
    }
}

void PID_Deviation_Loop(void)//(方向外环)角度环  5ms
{
    uint8 line_seen = vision_link_read(vision_time_ms, &image_error);
    right_angle_update(line_seen);
    if (!vision_control_ready() || (!line_seen && !imu_angle_flag))
    {
        /* direction run without a fresh line for VISION_MAX_AGE_MS: end the run, relaunch by hand */
        if (Loop_Set == Loop_Type_Deviation && launch_flag && !launch_delay_flag && !IMUinit_flag)
        {
            launch_flag = 0;
            STOP_reason = 3;
        }
        image_error = 0;
        pid_reset_history(&Deviation_pid);
        return;
    }
    if (imu_angle_flag)
    {
        float e = target_imu - imu_sum;
        angle_error = (int16)(e >= 0 ? e + 0.5f : e - 0.5f);
    }
    if (ra_kick)
    {
        Deviation_pid.last_error = (float)(imu_angle_flag ? angle_error : -image_error);
        ra_kick = 0;
    }
    if(imu_angle_flag == 0)
        PID_Control_Pos(&Deviation_pid, 0, image_error);//image_error用赛道中线减屏幕中线
    else
    {
        PID_Control_Pos(&Deviation_pid, 0, -angle_error);
        Deviation_pid.PIDout = func_limit(Deviation_pid.PIDout, ra_rate);
    }

}

void PID_Angle_Loop(void)//(角度内环)角速度环  2ms
{
    static uint16 Angle_stop_small = 0;
    static uint16 Angle_stop_big = 0;
    if (vision_imu_ready) Gyro_Translate();
    if (!vision_control_ready())
    {
        pid_reset_history(&Angle_pid);
        Angle_stop_small = Angle_stop_big = 0;
        return;
    }//陀螺仪数据
    if(Loop_Set == Loop_Type_Deviation)//(角度外环)角度环调参
    {
        PID_Control_Inc(&Angle_pid, func_limit(Deviation_pid.PIDout, 32767), Gyro_Data_z);//陀螺仪左正右负
        Angle_pid.PIDout = (Angle_launch_flag == 0) ? 0 : Angle_pid.PIDout;
        Angle_pid.integral = (Angle_launch_flag == 0) ? 0 : Angle_pid.integral;
        if(launch_flag == 1 && launch_delay_flag == 0 && IMUinit_flag == 0)
        {
            if(Deviation_pid.PIDout > Gyro_Data_z)
            {
                Angle_stop_big ++;
                Angle_stop_small = 0;
            }
            else if(Deviation_pid.PIDout < Gyro_Data_z)
            {
                Angle_stop_small ++;
                Angle_stop_big = 0;
            }
            if(Angle_stop_big > protect_time || Angle_stop_small > protect_time )
            {
                launch_flag = 0;
                STOP_reason = 1;
                Angle_stop_big = 0;
                Angle_stop_small = 0;
            }
        }


    }
    else//(角度内环)角速度环调参
    {
        PID_Control_Inc(&Angle_pid, set_Loop_Type_Angle, Gyro_Data_z);//陀螺仪左正右负
        Angle_pid.PIDout = (Angle_launch_flag == 0) ? 0 : Angle_pid.PIDout;
        Angle_pid.integral = (Angle_launch_flag == 0) ? 0 : Angle_pid.integral;
    }
}

void PID_Speed_Loop(void)//速度环  2ms
{
    static uint16 SpeedL_stop_small = 0;
    static uint16 SpeedL_stop_big = 0;
    static uint16 SpeedR_stop_small = 0;
    static uint16 SpeedR_stop_big = 0;
    encoder_count_get();
    if (!vision_control_ready())
    {
        pid_reset_history(&motorL_pid);
        pid_reset_history(&motorR_pid);
        SpeedL_stop_small = SpeedL_stop_big = 0;
        SpeedR_stop_small = SpeedR_stop_big = 0;
        set_speed = 0;
        Motor_Out(0, 0);
        return;
    }//编码器读取
    if(Loop_Set == Loop_Type_Deviation)//(角度外环)角度环调参
    {
        PID_Control_Inc(&motorL_pid, set_speed - Angle_pid.PIDout, encoder_L);
        PID_Control_Inc(&motorR_pid, set_speed + Angle_pid.PIDout, encoder_R);

        if(launch_flag == 1 && launch_delay_flag == 0 && IMUinit_flag == 0)
        {
            if(set_speed - Angle_pid.PIDout > encoder_L)
            {
                SpeedL_stop_big ++;
                SpeedL_stop_small = 0;
            }
            else if(set_speed - Angle_pid.PIDout < encoder_L)
            {
                SpeedL_stop_small ++;
                SpeedL_stop_big = 0;
            }

            if(set_speed + Angle_pid.PIDout > encoder_R)
            {
                SpeedR_stop_big ++;
                SpeedR_stop_small = 0;
            }
            else if(set_speed + Angle_pid.PIDout < encoder_R)
            {
                SpeedR_stop_small ++;
                SpeedR_stop_big = 0;
            }
            if(SpeedL_stop_small > protect_time || SpeedR_stop_small > protect_time || SpeedL_stop_big > protect_time || SpeedR_stop_big > protect_time )
            {
                launch_flag = 0;
                STOP_reason = 2;
                SpeedL_stop_small = 0;
                SpeedL_stop_big = 0;
                SpeedR_stop_small = 0;
                SpeedR_stop_big = 0;
            }
        }
        if(launch_flag == 1)
            Motor_Out(motorL_pid.PIDout, motorR_pid.PIDout);//电机输出
        else
            Motor_Out(0, 0);

    }
    else if(Loop_Set == Loop_Type_Angle)//(角度内环)角速度环调参
    {
        PID_Control_Inc(&motorL_pid, - Angle_pid.PIDout, encoder_L);
        PID_Control_Inc(&motorR_pid, Angle_pid.PIDout, encoder_R);
        if(launch_flag == 1)
            Motor_Out(motorL_pid.PIDout, motorR_pid.PIDout);//电机输出
        else
            Motor_Out(0, 0);
    }
    else if(Loop_Set == Loop_Type_Speed)//速度环调参
    {
        if(launch_flag == 1)
        {
            if(Wheel_selection == left)
            {
                PID_Control_Inc(&motorL_pid, set_speed, encoder_L);
                Motor_Out(motorL_pid.PIDout, 0);//电机输出
            }
            if(Wheel_selection == right)
            {
                PID_Control_Inc(&motorR_pid, set_speed, encoder_R);
                Motor_Out(0, motorR_pid.PIDout);//电机输出
            }
        }
        else
        {
            Motor_Out(0, 0);
        }
    }
}

