static uint32_t last_frame;
static uint32_t sample_ms;
static int16_t sample_px;
static uint8_t sample_valid;
static uint8_t received_frame;
static int8_t corner_dir;      /* right angle in the newest processed frame: +1 left, -1 right, 0 none */
static uint8_t corner_row;
static uint32_t corner_seq;    /* processed frames */
static uint32_t dbg_frames, dbg_valid, dbg_proc_us, dbg_last_ms;
static int16_t dbg_px;
extern uint8 ouc_frame[OUC_IMAGE_HEIGHT][OUC_IMAGE_WIDTH];
extern uint8 mt9v03x_image_bin[OUC_IMAGE_HEIGHT][OUC_IMAGE_WIDTH];
