void vision_link_init(void)
{
    boolean enabled = IfxCpu_disableInterrupts();
    vision_time_ms = 0;
    vision_frame_seq = 0;
    vision_capture_ms = 0;
    vision_hardware_ready = 0;
    vision_camera_ready = 0;
    vision_imu_ready = 0;
    vision_parameters_confirmed = 1;   /* tuning build: 方向链按调车步骤先架空核对, 再跑方向模式 */
    last_frame = sample_ms = 0;
    sample_px = 0;
    sample_valid = received_frame = 0;
    corner_dir = 0;
    corner_row = 0;
    corner_seq = 0;
    IfxCpu_restoreInterrupts(enabled);
}

uint32_t vision_link_corner(int8_t *dir, uint8_t *row)
{
    uint32_t seq;
    boolean enabled = IfxCpu_disableInterrupts();
    *dir = corner_dir;
    *row = corner_row;
    seq = corner_seq;
    IfxCpu_restoreInterrupts(enabled);
    return seq;
}

uint8_t vision_link_publish(int16_t px, uint8_t valid,
                            uint32_t frame_seq, uint32_t capture_ms)
{
    boolean enabled = IfxCpu_disableInterrupts();
    if (received_frame && frame_seq == last_frame)
    {
        IfxCpu_restoreInterrupts(enabled);
        return 0;
    }
    last_frame = frame_seq;
    received_frame = 1;
    /* An invalid frame keeps the last valid sample; its age then decides when control stops. */
    if (valid && px >= -OUC_IMAGE_WIDTH && px <= OUC_IMAGE_WIDTH)
    {
        sample_ms = capture_ms;
        sample_px = px;
        sample_valid = 1;
    }
    IfxCpu_restoreInterrupts(enabled);
    return 1;
}

uint8_t vision_link_read(uint32_t now_ms, int16_t *right_positive_px)
{
    uint8_t valid;
    boolean enabled;
    if (!right_positive_px) return 0;
    enabled = IfxCpu_disableInterrupts();
    valid = received_frame && sample_valid &&
            (uint32_t)(now_ms - sample_ms) <= VISION_MAX_AGE_MS;
    *right_positive_px = valid ? sample_px : 0;
    IfxCpu_restoreInterrupts(enabled);
    return valid;
}

uint8_t vision_control_ready(void)
{
    int16_t error_px;
    if (!vision_imu_ready || !launch_flag || launch_delay_flag || IMUinit_flag) return 0;
    if (Loop_Set != Loop_Type_Deviation) return 1;   /* speed / yaw-rate tuning needs no camera */
    /* right-angle turn (imu_angle_flag): steered by the gyro, runs without a fresh line */
    return vision_camera_ready && vision_parameters_confirmed &&
           (imu_angle_flag || vision_link_read(vision_time_ms, &error_px));
}

void vision_process_pending(void)
{
    uint8_t valid, row = 0;
    int16_t px;
    int8_t dir;
    uint32_t t0;
    boolean enabled;
    if (!vision_camera_ready || !mt9v03x_finish_flag) return;
    if (received_frame && vision_frame_seq == last_frame)
    {
        mt9v03x_finish_flag = 0;
        return;
    }
    /* VSYNC skips this held buffer until foreground finishes consuming it. */
    t0 = system_getval();
    px = ouc_vision_process(&mt9v03x_image[0][0], &valid);
    dir = ouc_right_angle(&row);
    dbg_proc_us = (system_getval() - t0) / 100;   /* STM 100 MHz */
    dbg_frames++;
    if (valid) { dbg_valid++; dbg_px = px; }
    vision_link_publish(px, valid, vision_frame_seq, vision_capture_ms);
    enabled = IfxCpu_disableInterrupts();
    corner_dir = dir;
    corner_row = row;
    corner_seq++;
    IfxCpu_restoreInterrupts(enabled);
    mt9v03x_finish_flag = 0;
}

#define REC_N 1000                       /* 2 s at 2 ms */
#pragma section all "cpu0_dsram"
static int16_t rec[REC_N][6];           /* set_speed, encL, encR, pwmL, pwmR, gyro*10 */
#pragma section all restore
static volatile uint16_t rec_n;
static uint8_t rec_was_running;

void vision_debug_record(void)
{
    uint8_t running = launch_flag && !launch_delay_flag && !IMUinit_flag;
    if (running && !rec_was_running) rec_n = 0;   /* a new run starts a fresh record */
    rec_was_running = running;
    if (!running || rec_n >= REC_N) return;
    rec[rec_n][0] = set_speed;
    rec[rec_n][1] = encoder_L;
    rec[rec_n][2] = encoder_R;
    rec[rec_n][3] = (int16_t)motorL_pid.PIDout;
    rec[rec_n][4] = (int16_t)motorR_pid.PIDout;
    rec[rec_n][5] = (int16_t)(Gyro_Data_z * 10.0f);
    rec_n++;
}

static void dump_record(void)
{
    char line[64];
    int n = sprintf(line, "\r\nLOG %u\r\n", (unsigned)rec_n);
    debug_send_buffer((const uint8 *)line, (uint32)n);
    for (uint16_t i = 0; i < rec_n; i++)
    {
        n = sprintf(line, "%u,%d,%d,%d,%d,%d,%d\r\n", (unsigned)i, rec[i][0], rec[i][1], rec[i][2], rec[i][3], rec[i][4], rec[i][5]);
        debug_send_buffer((const uint8 *)line, (uint32)n);
    }
    debug_send_buffer((const uint8 *)"END\r\n", 5);
}

static void dump_frame(const char *kind, const uint8 *pixels)
{
    char head[48];
    int n = sprintf(head, "\r\nIMG %s %d %d %lu\r\n", kind, OUC_IMAGE_WIDTH, OUC_IMAGE_HEIGHT, (unsigned long)last_frame);
    debug_send_buffer((const uint8 *)head, (uint32)n);
    debug_send_buffer(pixels, OUC_IMAGE_WIDTH * OUC_IMAGE_HEIGHT);
    debug_send_buffer((const uint8 *)"\r\nEND\r\n", 7);
}

void vision_debug_poll(void)
{
    uint8 cmd;
    char line[160];
    int n;
    /* blocking: a frame dump at 115200 baud takes about 2 s; motors are locked in this build */
    while (debug_read_ring_buffer(&cmd, 1))
    {
        if (cmd == 'I') dump_frame("gray", &ouc_frame[0][0]);
        if (cmd == 'B') dump_frame("bin", &mt9v03x_image_bin[0][0]);
        if (cmd == 'S' && !launch_flag) dump_record();          /* ~2.5 s blocking: only while stopped */
        if (cmd == 'Z') encoder_L_total = encoder_R_total = 0;   /* push the car 1 m, read encL/encR */
    }
    if ((uint32_t)(vision_time_ms - dbg_last_ms) < 1000u) return;
    dbg_last_ms = vision_time_ms;
    if (!vision_camera_ready)   /* bring-up: retry, about 0.3 s blocking per try */
    {
        vision_camera_ready = (mt9v03x_init() == 0);
        n = sprintf(line, "camera retry: %s\r\n", vision_camera_ready ? "ok" : "fail");
        debug_send_buffer((const uint8 *)line, (uint32)n);
    }
    n = sprintf(line, "t=%lu vbat_mv=%lu cam=%u hw=%u seq=%lu fps=%lu valid=%lu proc_us=%lu px=%d Lp=%d Rp=%d gray=%u encL=%ld encR=%ld\r\n",
                (unsigned long)vision_time_ms,
                (unsigned long)adc_mean_filter_convert(ADC0_CH11_A11, 8) * 3300ul * 11ul / 4095ul,
                vision_camera_ready, vision_hardware_ready,
                (unsigned long)vision_frame_seq, (unsigned long)dbg_frames, (unsigned long)dbg_valid,
                (unsigned long)dbg_proc_us, dbg_px, L_point, R_point, img_avg_gray, (long)encoder_L_total, (long)encoder_R_total);
    debug_send_buffer((const uint8 *)line, (uint32)n);
    dbg_frames = dbg_valid = 0;
}

