//蓝牙
void Bluetooth_UART(void)
{
    // -------------------- 发送数据(给手机蓝牙发)--------------------

    if(Loop_Set == Loop_Type_Deviation)
    {
        tx_pack.floats[0] = image_error;//image_error
        tx_pack.shorts[0] = set_speed_surface;//
        tx_pack.bytes[0] = STOP_reason;
    }
    else if(Loop_Set == Loop_Type_Speed)
    {
        if(Wheel_selection == left)
        {
            tx_pack.floats[0] = encoder_L;
            tx_pack.shorts[0] = set_speed;
        }
        else if(Wheel_selection == right)
        {
            tx_pack.floats[0] = encoder_R;
            tx_pack.shorts[0] = set_speed;
        }
        tx_pack.bytes[0] = 0;
    }
    else if(Loop_Set == Loop_Type_Angle)
    {
        tx_pack.floats[0] = Gyro_Data_z;
        tx_pack.shorts[0] = set_Loop_Type_Angle;
        tx_pack.bytes[0] = 0;
    }


    // 发送数据包
    {
        static uint32 last_tx_ms;   /* 9600 baud: one packet blocks ~10 ms, so send at 10 Hz, receive every loop */
        if ((uint32)(vision_time_ms - last_tx_ms) >= 100u)
        {
            last_tx_ms = vision_time_ms;
            sendValuePack(&tx_pack);
        }
    }
    // -------------------- 接收并解析数据(手机蓝牙往这儿发) --------------------
    // 读取数据包（返回1表示收到有效数据，0表示未收到）


    rx_flag = readValuePack(&rx_pack);

    if(rx_pack.bools[0] == 0)//停车(launch)
    {
   //     launch_flag = 0;
    }

    if(rx_flag)
    {
        if(Last_rx_pack.bools[0] != rx_pack.bools[0] && rx_pack.bools[0] == 1)//发车(launch)
        {

            launch_delay_flag = 1; launch_flag = 1;
        }
        if(Last_rx_pack.bools[0] != rx_pack.bools[0] && rx_pack.bools[0] == 0)//停车(手机开关拨回)
        {
            launch_flag = 0;
        }
        if(launch_flag == 0 && rx_pack.bytes[0] <= 3)//调车模式只在停车时切换
        {
            Loop_Set = (rx_pack.bytes[0] == 0) ? Loop_Type_Deviation : (rx_pack.bytes[0] == 3) ? Loop_Type_Angle : Loop_Type_Speed;
            Wheel_selection = (rx_pack.bytes[0] == 2) ? right : left;
        }
        fan_target_duty = (uint16)((rx_pack.bytes[1] > 100) ? 100 : rx_pack.bytes[1]) * 100u;//风机功率%, 发车后才转

        if(Loop_Set == Loop_Type_Deviation)
        {
            if(Last_rx_pack.bytes[0] != rx_pack.bytes[0])
            {

            }

            if(Last_rx_pack.shorts[0] != rx_pack.shorts[0])//设速度
            {
                set_speed_Debug = rx_pack.shorts[0];
                set_speed_surface = set_speed_Debug;//调车: 按这个速度跑, Kp/Kd 也写进这个速度档
            }

            if(Last_rx_pack.floats[0] != rx_pack.floats[0])//设kp
            {
                Deviation_pid.Kp.speed[(int16)(Speed_index(set_speed_Debug))] = rx_pack.floats[0];
            }

            if(Last_rx_pack.floats[1] != rx_pack.floats[1])//设kd
            {
                Deviation_pid.Kd.speed[(int16)(Speed_index(set_speed_Debug))] = rx_pack.floats[1];
            }
        }
        else if(Loop_Set == Loop_Type_Angle)
        {
            if(Last_rx_pack.shorts[0] != rx_pack.shorts[0])//设速度
            {
                set_Loop_Type_Angle = rx_pack.shorts[0];
            }

            if(Last_rx_pack.floats[0] != rx_pack.floats[0])//设kp
            {
                Angle_pid.Kp.present = rx_pack.floats[0];
            }

            if(Last_rx_pack.floats[1] != rx_pack.floats[1])//设ki
            {
                Angle_pid.Ki.present = rx_pack.floats[1];
            }
        }
        else if(Loop_Set == Loop_Type_Speed)
        {
            if(Last_rx_pack.shorts[0] != rx_pack.shorts[0])//设速度
            {
                set_speed_surface = rx_pack.shorts[0];
            }

            if(Wheel_selection == left)
            {
                if(Last_rx_pack.floats[0] != rx_pack.floats[0])//设kp
                {
                    motorL_pid.Kp.present = rx_pack.floats[0];
                }

                if(Last_rx_pack.floats[1] != rx_pack.floats[1])//设ki
                {
                    motorL_pid.Ki.present = rx_pack.floats[1];
                }
            }

            if(Wheel_selection == right)
            {
                if(Last_rx_pack.floats[0] != rx_pack.floats[0])//设kp
                {
                    motorR_pid.Kp.present = rx_pack.floats[0];
                }

                if(Last_rx_pack.floats[1] != rx_pack.floats[1])//设ki
                {
                    motorR_pid.Ki.present = rx_pack.floats[1];
                }
            }

        }


        Last_rx_pack.bools[0] = rx_pack.bools[0];
        Last_rx_pack.bytes[0] = rx_pack.bytes[0];
        Last_rx_pack.shorts[0] = rx_pack.shorts[0];
        Last_rx_pack.floats[0] = rx_pack.floats[0];
        Last_rx_pack.floats[1] = rx_pack.floats[1];
        rx_flag = 0;
    }


}



//static uint8 bits[] = {0x01,0x02,0x04,0x08,0x10,0x20,0x40,0x80};
const uint32 VALUEPACK_INDEX_RANGE = VALUEPACK_BUFFER_SIZE << 3;
const uint16 TXPACK_BYTE_SIZE = TXPACK_BYTE_SIZE_FIX;
const uint16 RXPACK_BYTE_SIZE = RXPACK_BYTE_SIZE_FIX;
// 全局变量延迟初始化（放到init函数里）
uint16 rx_pack_length;

// 3. 缓冲区定义（用固定宏）
static uint8 vp_rxbuff[VALUEPACK_BUFFER_SIZE];
static uint8 vp_txbuff[TXPACK_BYTE_SIZE_FIX + 3];

// 4. 接收解析相关变量
static uint32 this_index = 0;
static uint32 last_index = 0;
static uint32 rxIndex = 0;
static uint32 rdIndex = 0;
static uint32 err = 0;

/**
 * @brief 初始化ValuePack（仅初始化缓冲区，串口由逐飞库初始化）
 */
void initValuePack(void)
{
    // 初始化rx_pack_length（运行期赋值，避开编译期常量要求）
    rx_pack_length = RXPACK_BYTE_SIZE_FIX + 3;
    // 清空缓冲区
    memset(vp_rxbuff, 0, VALUEPACK_BUFFER_SIZE);
    memset(vp_txbuff, 0, TXPACK_BYTE_SIZE_FIX + 3);
    // 逐飞库无线串口已在外部初始化（wireless_uart_init），这里无需重复配置
}

/**
 * @brief 逐飞库无线串口发送缓冲区数据（替换STM32 DMA发送）
 */
static void sendBuffer(uint8 *p, uint16 length)
{
    // 调用逐飞库无线串口发送函数
    wireless_uart_send_buffer(p, length);
    // 简单延时保证发送完成（可选）
    // system_delay_ms(1);
}

/**
 * @brief 解析接收缓冲区的数据包
 */
uint8 readValuePack(RxPack *rx_pack_ptr)
{
    uint8 isok = 0;
    uint16 rdi, rdii, idl, idi;
    uint32 idc;
    uint8 sum = 0;
    int16 s;
    uint8 loop_safe = 100; // 最多循环100次，防止极端情况
    uint8 loop_safe_2 = 100;

    uint32 rx_len = 0;
    rx_len = wireless_uart_read_buffer(vp_rxbuff + this_index, VALUEPACK_BUFFER_SIZE - this_index);
    if(rx_len > 0)
    {
        this_index += rx_len;
        // 循环缓冲区处理
        if(this_index >= VALUEPACK_BUFFER_SIZE)
            this_index = 0;
    }

    // 以下原有解析逻辑完全不变！！！
    if (this_index < last_index)
    {
        rxIndex += VALUEPACK_BUFFER_SIZE + this_index - last_index;
    }
    else
    {
        rxIndex += this_index - last_index;
    }

    if(rx_pack_length > 0 && (rxIndex >= rx_pack_length))
    {
        while ((rdIndex + 2u * rx_pack_length) <= rxIndex && loop_safe-- > 0)   // 留最后两包给逐字节找包头, 坏包后能重新对齐
        {
            rdIndex += rx_pack_length;
        }
    }
    else
    {
        rdIndex = 0;
    }

    while ((rxIndex >= rx_pack_length) && (rdIndex <= (rxIndex - rx_pack_length)) && (loop_safe_2-- > 0))
    {
        rdi = rdIndex % VALUEPACK_BUFFER_SIZE;
        rdii = rdi + 1;

        if (vp_rxbuff[rdi] == PACK_HEAD)
        {
            if (vp_rxbuff[(rdi + RXPACK_BYTE_SIZE + 2) % VALUEPACK_BUFFER_SIZE] == PACK_TAIL)
            {
                sum = 0;
                for (s = 0; s < RXPACK_BYTE_SIZE; s++)
                {
                    rdi++;
                    if (rdi >= VALUEPACK_BUFFER_SIZE)
                    {
                        rdi -= VALUEPACK_BUFFER_SIZE;
                    }
                    sum += vp_rxbuff[rdi];
                }
                rdi++;
                if (rdi >= VALUEPACK_BUFFER_SIZE)
                {
                    rdi -= VALUEPACK_BUFFER_SIZE;
                }

                if (sum == vp_rxbuff[rdi])
                {
                    // 1. 解析Bool
                    #if RX_BOOL_NUM > 0
                    idc = (uint32)rx_pack_ptr->bools;
                    idl = (RX_BOOL_NUM + 7) >> 3;
                    for (idi = 0; idi < idl; idi++)
                    {
                        if (rdii >= VALUEPACK_BUFFER_SIZE)
                        {
                            rdii -= VALUEPACK_BUFFER_SIZE;
                        }
                        *((uint8 *)idc) = vp_rxbuff[rdii];
                        rdii++;
                        idc++;
                    }
                    #endif

                    // 2. 解析Byte
                    #if RX_BYTE_NUM > 0
                    idc = (uint32)(rx_pack_ptr->bytes);
                    idl = RX_BYTE_NUM;
                    for (idi = 0; idi < idl; idi++)
                    {
                        if (rdii >= VALUEPACK_BUFFER_SIZE)
                        {
                            rdii -= VALUEPACK_BUFFER_SIZE;
                        }
                        *((uint8 *)idc) = vp_rxbuff[rdii];
                        rdii++;
                        idc++;
                    }
                    #endif

                    // 3. 解析Short
                    #if RX_SHORT_NUM > 0
                    idc = (uint32)(rx_pack_ptr->shorts);
                    idl = RX_SHORT_NUM << 1;
                    for (idi = 0; idi < idl; idi++)
                    {
                        if (rdii >= VALUEPACK_BUFFER_SIZE)
                        {
                            rdii -= VALUEPACK_BUFFER_SIZE;
                        }
                        *((uint8 *)idc) = vp_rxbuff[rdii];
                        rdii++;
                        idc++;
                    }
                    #endif

                    // 4. 解析Int
                    #if RX_INT_NUM > 0
                    idc = (uint32)(&(rx_pack_ptr->integers[0]));
                    idl = RX_INT_NUM << 2;
                    for (idi = 0; idi < idl; idi++)
                    {
                        if (rdii >= VALUEPACK_BUFFER_SIZE)
                        {
                            rdii -= VALUEPACK_BUFFER_SIZE;
                        }
                        *((uint8 *)idc) = vp_rxbuff[rdii];
                        rdii++;
                        idc++;
                    }
                    #endif

                    // 5. 解析Float
                    #if RX_FLOAT_NUM > 0
                    idc = (uint32)(&(rx_pack_ptr->floats[0]));
                    idl = RX_FLOAT_NUM << 2;
                    for (idi = 0; idi < idl; idi++)
                    {
                        if (rdii >= VALUEPACK_BUFFER_SIZE)
                        {
                            rdii -= VALUEPACK_BUFFER_SIZE;
                        }
                        *((uint8 *)idc) = vp_rxbuff[rdii];
                        rdii++;
                        idc++;
                    }
                    #endif

                    err = rdii;
                    rdIndex += rx_pack_length;
                    isok = 1;
                }
                else
                {
                    rdIndex++;
                    err++;
                }
            }
            else
            {
                rdIndex++;
                err++;
            }
        }
        else
        {
            rdIndex++;
            err++;
        }
    }
    if(loop_safe_2 == 0)
    {
        rdIndex = 0;
        rxIndex = 0;
        err = 0;
    }

    last_index = this_index;
    return isok;
}

/**
 * @brief 组包并发送数据包（原有逻辑完全不变，仅替换长度宏）
 */
void sendValuePack(TxPack *tx_pack_ptr)
{
    uint16 loop;
//    uint8 valuepack_tx_bit_index = 0;
    uint16 valuepack_tx_index = 1;
    uint8 sum = 0;
    uint16 d;
    int32 i;

    vp_txbuff[0] = PACK_HEAD;
    sum = 0;

    // 1. 组包Bool（原逻辑不变）
    #if TX_BOOL_NUM > 0
    for (loop = 0; loop < TX_BOOL_NUM; loop ++)
    {
        if (tx_pack_ptr->bools[loop])
        {
            vp_txbuff[valuepack_tx_index] |= 0x01 << valuepack_tx_bit_index;
        }
        else
        {
            vp_txbuff[valuepack_tx_index] &= ~(0x01 << valuepack_tx_bit_index);
        }

        valuepack_tx_bit_index++;
        if (valuepack_tx_bit_index >= 8)
        {
            valuepack_tx_bit_index = 0;
            valuepack_tx_index++;
        }
    }
    if (valuepack_tx_bit_index != 0)
    {
        valuepack_tx_index++;
    }
    #endif

    // 2. 组包Byte（原逻辑不变）
    #if TX_BYTE_NUM > 0
    for (loop = 0; loop < TX_BYTE_NUM; loop ++)
    {
        vp_txbuff[valuepack_tx_index] = tx_pack_ptr->bytes[loop];
        valuepack_tx_index++;
    }
    #endif

    // 3. 组包Short（原逻辑不变）
    #if TX_SHORT_NUM > 0
    for (loop = 0; loop < TX_SHORT_NUM; loop ++)
    {
        vp_txbuff[valuepack_tx_index] = (uint8)(tx_pack_ptr->shorts[loop] & 0xFF);
        vp_txbuff[valuepack_tx_index + 1] = (uint8)((tx_pack_ptr->shorts[loop] >> 8) & 0xFF);
        valuepack_tx_index += 2;
    }
    #endif

    // 4. 组包Int（原逻辑不变）
    #if TX_INT_NUM > 0
    for (loop = 0; loop < TX_INT_NUM; loop ++)
    {
        i = tx_pack_ptr->integers[loop];
        vp_txbuff[valuepack_tx_index] = (uint8)(i & 0xFF);
        vp_txbuff[valuepack_tx_index + 1] = (uint8)((i >> 8) & 0xFF);
        vp_txbuff[valuepack_tx_index + 2] = (uint8)((i >> 16) & 0xFF);
        vp_txbuff[valuepack_tx_index + 3] = (uint8)((i >> 24) & 0xFF);
        valuepack_tx_index += 4;
    }
    #endif

    // 5. 组包Float（原逻辑不变）
    #if TX_FLOAT_NUM > 0
    for (loop = 0; loop < TX_FLOAT_NUM; loop ++)
    {
        i = *(int32 *)(&(tx_pack_ptr->floats[loop]));
        vp_txbuff[valuepack_tx_index] = (uint8)(i & 0xFF);
        vp_txbuff[valuepack_tx_index + 1] = (uint8)((i >> 8) & 0xFF);
        vp_txbuff[valuepack_tx_index + 2] = (uint8)((i >> 16) & 0xFF);
        vp_txbuff[valuepack_tx_index + 3] = (uint8)((i >> 24) & 0xFF);
        valuepack_tx_index += 4;
    }
    #endif

    // 计算校验和（改用固定宏）
    for (d = 1; d <= TXPACK_BYTE_SIZE_FIX; d++)
    {
        sum += vp_txbuff[d];
    }

    // 设置校验和与包尾（改用固定宏）
    vp_txbuff[TXPACK_BYTE_SIZE_FIX + 1] = sum;
    vp_txbuff[TXPACK_BYTE_SIZE_FIX + 2] = PACK_TAIL;

    // 发送数据包（调用逐飞库发送函数）
    sendBuffer(vp_txbuff, TXPACK_BYTE_SIZE_FIX + 3);
}





























































































