#include "zf_common_headfile.h"


#define  Sendtime_interval_us   15000//发送时间间隔

// 1. 缓冲区大小（保持原有值）
#define VALUEPACK_BUFFER_SIZE 1024

// 2. 发送/接收数据类型数量（保持你的配置）
#define TX_BOOL_NUM  0
#define TX_BYTE_NUM  1
#define TX_SHORT_NUM 1
#define TX_INT_NUM   0
#define TX_FLOAT_NUM 1

#define RX_BOOL_NUM  1//只能是1
#define RX_BYTE_NUM  2  //byte0 调车模式, byte1 风机功率%
#define RX_SHORT_NUM 1  //int16
#define RX_INT_NUM   0  //int32
#define RX_FLOAT_NUM 2  //float

// 数据包头尾（保持不变）
#define PACK_HEAD 0xa5
#define PACK_TAIL 0x5a

// ！！！新增：编译期固定长度（解决TC264编译器E306报错）
// 计算逻辑：((1+7)>>3)=1 +1 +2 +4 +4 = 12
#define TXPACK_BYTE_SIZE_FIX 7
#define RXPACK_BYTE_SIZE_FIX 13   // 1 bool字节 + 2 byte + 2 short + 8 float

// 发送/接收数据包结构体（完全保留）
typedef struct
{
    #if TX_BOOL_NUM > 0
    uint8 bools[TX_BOOL_NUM];
    #endif
    #if TX_BYTE_NUM > 0
    uint8 bytes[TX_BYTE_NUM];
    #endif
    #if TX_SHORT_NUM > 0
    int16 shorts[TX_SHORT_NUM];
    #endif
    #if TX_INT_NUM > 0
    int32 integers[TX_INT_NUM];
    #endif
    #if TX_FLOAT_NUM > 0
    float floats[TX_FLOAT_NUM];
    #endif
    uint8 space; // 避免空结构体
} TxPack;

typedef struct
{
    #if RX_BOOL_NUM > 0
    uint8 bools[RX_BOOL_NUM];
    #endif
    #if RX_BYTE_NUM > 0
    uint8 bytes[RX_BYTE_NUM];
    #endif
    #if RX_SHORT_NUM > 0
    int16 shorts[RX_SHORT_NUM];
    #endif
    #if RX_INT_NUM > 0
    int32 integers[RX_INT_NUM];
    #endif
    #if RX_FLOAT_NUM > 0
    float floats[RX_FLOAT_NUM];
    #endif
    uint8 space; // 避免空结构体
} RxPack;


extern uint8 data_buffer[32];
extern int Received_data;
extern uint8 send_flag;
extern uint8 wireless_flag;

// 声明函数（简化初始化，波特率由逐飞库配置）
void Bluetooth_UART(void);
void initValuePack(void);
uint8 readValuePack(RxPack *rx_pack_ptr);
void sendValuePack(TxPack *tx_pack_ptr);

#endif

