#define WIRELESS_FITTED 1   // 蓝牙模块接母板 P7 无线模块串口; 置0则不初始化也不调 Bluetooth_UART(否则写未初始化的 UART2 会卡死主循环)
#define LAUNCH_KEY      P20_6   // 母板按键 S2: 按一下发车(2.5s后起步), 再按一下停车


// 将本语句与#pragma section all restore语句之间的全局变量都放在CPU0的RAM中

