// **************************** 代码区域 ****************************
int core0_main(void)
{
    clock_init();                   // 获取时钟频率<务必保留>
    debug_init();                   // 初始化默认调试串口
    // 此处编写用户代码 例如外设初始化代码等
    uint8 imu_ok;
    uint8 camera_ok;
    vision_link_init();
    pwm_duty_init();
    pwm_init(Brushless_Motor, FAN_PWM_FREQ, 0);
    adc_init(ADC0_CH11_A11, ADC_12BIT);   // 电池电压: VCCBAT 经 200K/20K 分压到 AN11
    system_delay_ms(500);
    imu_ok = (imu660rc_init(IMU660RC_QUARTERNION_DISABLE) == 0);
    system_delay_ms(500);
    if (imu_ok) imu_zero_init();//陀螺仪测定零漂,时间departure_zero_buffer(ms)
    encoder_init();
    PID_Init();
    ouc_vision_init();
    camera_ok = (mt9v03x_init() == 0);
    vision_hardware_ready = imu_ok && camera_ok;
    vision_camera_ready = camera_ok;
    vision_imu_ready = imu_ok;
    gpio_init(LAUNCH_KEY, GPI, GPIO_HIGH, GPI_PULL_UP);
#if WIRELESS_FITTED
    wireless_uart_init();
    initValuePack();
#endif
    printf("\r\nboot imu_ok=%d camera_ok=%d\r\n", imu_ok, camera_ok);
    system_delay_ms(50);

    pit_ms_init(CCU60_CH0, 5);//中断5ms
    pit_ms_init(CCU60_CH1, 2);//中断2ms
    pit_ms_init(CCU61_CH0, 5);//中断5ms
    pit_ms_init(CCU61_CH1, 2);//中断2ms
    // Fan initialized before timer interrupts. //有刷负压风机初始化,默认关
    // 此处编写用户代码 例如外设初始化代码等
    cpu_wait_event_ready();         // 等待所有核心初始化完毕
    system_start();
    while (TRUE)
    {
        // 此处编写需要循环执行的代码
        vision_process_pending();
        vision_debug_poll();
        {
            static uint8 key_last = 1;
            static uint32 key_ms;
            uint8 key = gpio_get_level(LAUNCH_KEY);
            if (key != key_last && (uint32)(vision_time_ms - key_ms) > 30u)   // 30 ms 消抖
            {
                key_ms = vision_time_ms;
                key_last = key;
                if (key == 0)
                {
                    if (launch_flag) launch_flag = 0;
                    else { launch_delay_flag = 1; launch_flag = 1; }
                }
            }
        }
        flash_change_check();
        if(launch_flag == 1)
        {
            if(launch_delay_flag == 1)
            {
//                LED_ON(P20_8);
                Brushless_Motor_begin_flag = 1;
                if(non_blocking_delay(departure_delay))
                {
//                    LED_OFF(P20_8);
//                    LED_ON(P20_9);
                    imu_calibration_reset(1);       //IMUinit_flag和launch_delay_flag位置不能换
                    launch_delay_flag = 0;
                }
                //system_delay_ms(departure_delay);

            }
            if(launch_delay_flag == 0)
            {
//                LED_OFF(P20_9);
//                set_speed = set_speed_surface;//放定时器里缓启动了
                if(IMUinit_flag == 0)
                {
                    Angle_launch_flag = 1;
                }
            }
        }
        else
        {
            Brushless_count = 0;
            imu_calibration_reset(0);
            non_blocking_delay_reset();
            launch_delay_flag = 1;
            Angle_launch_flag = 0;
            Brushless_Motor_begin_flag = 0;
        }

#if WIRELESS_FITTED
        Bluetooth_UART();//这是我用来远程调参的蓝牙
#endif

        // 此处编写需要循环执行的代码
    }
}

