// 对于TC系列默认是不支持中断嵌套的，希望支持中断嵌套需要在中断内使用 interrupt_global_enable(0); 来开启中断嵌套
// 简单点说实际上进入中断后TC系列的硬件自动调用了 interrupt_global_disable(); 来拒绝响应任何的中断，因此需要我们自己手动调用 interrupt_global_enable(0); 来开启中断的响应。

// **************************** PIT中断函数 ****************************

IFX_INTERRUPT(cc60_pit_ch0_isr, 0, CCU6_0_CH0_ISR_PRIORITY)
{
    interrupt_global_enable(0);                     // 开启中断嵌套
    pit_clear_flag(CCU60_CH0);

    PID_Deviation_Loop();//方向外环(角度环)

}


IFX_INTERRUPT(cc60_pit_ch1_isr, 0, CCU6_0_CH1_ISR_PRIORITY)
{
    interrupt_global_enable(0);                     // 开启中断嵌套
    pit_clear_flag(CCU60_CH1);
    vision_time_ms += 2u;
    timing_count += 2u;
//    Gyro_Translate();//陀螺仪数据
//    encoder_count_get();//编码器读取
/*这两行代码取消注释放这儿是为了想看数据的时候打开，并把方向内环和速度环注释，这样可以在不影响观察数据的同时防止车辆失控(你驱动部分有开关，可以保证车轮不会动的话可以不用管)*/

    PID_Angle_Loop();//方向内环(角速度环)
    PID_Speed_Loop();//速度环
    vision_debug_record();//调车: 记录每次发车前 2 s, 串口 'S' 导出
}

IFX_INTERRUPT(cc61_pit_ch0_isr, 0, CCU6_1_CH0_ISR_PRIORITY)
{
    interrupt_global_enable(0);                     // 开启中断嵌套
    pit_clear_flag(CCU61_CH0);


    Brushless_Motor_Speed(fan_target_duty);
    speed_control();

}

IFX_INTERRUPT(cc61_pit_ch1_isr, 0, CCU6_1_CH1_ISR_PRIORITY)
{
    interrupt_global_enable(0);                     // 开启中断嵌套
    pit_clear_flag(CCU61_CH1);


}
